<?php
if (!defined('ABSPATH')) exit;
function an_setup(){add_theme_support('title-tag');add_theme_support('post-thumbnails');add_theme_support('html5',array('search-form','gallery','caption'));}
add_action('after_setup_theme','an_setup');
function an_assets(){wp_enqueue_style('atelier-north',get_stylesheet_uri(),array(),'1.0.0');wp_enqueue_script('atelier-north',get_template_directory_uri().'/assets/shop.js',array(),'1.0.0',true);}
add_action('wp_enqueue_scripts','an_assets');
function an_products(){register_post_type('an_product',array('labels'=>array('name'=>'Store products','singular_name'=>'Store product'),'public'=>false,'show_ui'=>true,'show_in_menu'=>true,'supports'=>array('title','editor','excerpt','thumbnail'),'menu_icon'=>'dashicons-cart'));}
add_action('init','an_products');
function an_seed(){an_products();if(get_option('an_seeded'))return;$products=array(array('Forma Vessel','Decor',68,'Sculptural stoneware with a gently rippled silhouette.'),array('Meridian Desk Lamp','Lighting',185,'A warm brushed-brass finish and classic articulated form.'),array('Walnut Ritual Tray','Kitchen & dining',54,'A sculpted walnut tray for understated everyday rituals.'),array('Still Linen Throw','Textiles',96,'A tactile woven throw in a timeless taupe shade.'),array('Noir Ceramic Cup','Kitchen & dining',24,'A softly textured matte ceramic cup.'),array('Arc Marble Bookends','Decor',88,'Two sculptural marble pieces with natural veining.'));foreach($products as $i=>$p){$id=wp_insert_post(array('post_type'=>'an_product','post_status'=>'publish','post_title'=>$p[0],'post_content'=>$p[3],'post_excerpt'=>$p[3],'menu_order'=>$i),true);if(!is_wp_error($id)){update_post_meta($id,'an_price',$p[2]);update_post_meta($id,'an_category',$p[1]);update_post_meta($id,'an_image',$i);}}update_option('an_seeded',1);}
add_action('after_switch_theme','an_seed');
function an_meta(){add_meta_box('an_product_details','Catalogue details','an_meta_fields','an_product','side');}add_action('add_meta_boxes','an_meta');
function an_meta_fields($post){wp_nonce_field('an_save_product','an_nonce');$price=get_post_meta($post->ID,'an_price',true);$category=get_post_meta($post->ID,'an_category',true);?><p><label for="an_price">Price (USD)</label><input name="an_price" id="an_price" type="number" step="0.01" min="0" value="<?php echo esc_attr($price); ?>"></p><p><label for="an_category">Category</label><select id="an_category" name="an_category"><?php foreach(array('Decor','Lighting','Kitchen & dining','Textiles') as $c){?><option <?php selected($category,$c);?>><?php echo esc_html($c);?></option><?php }?></select></p><?php }
function an_save($id){if(!isset($_POST['an_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['an_nonce'])),'an_save_product')||!current_user_can('edit_post',$id)||wp_is_post_autosave($id)||wp_is_post_revision($id))return;$price=isset($_POST['an_price'])?max(0,(float)$_POST['an_price']):0;$cat=isset($_POST['an_category'])?sanitize_text_field(wp_unslash($_POST['an_category'])):'Decor';if(!in_array($cat,array('Decor','Lighting','Kitchen & dining','Textiles'),true))$cat='Decor';update_post_meta($id,'an_price',$price);update_post_meta($id,'an_category',$cat);}add_action('save_post_an_product','an_save');
function an_favicon(){echo '<link rel="icon" type="image/svg+xml" href="'.esc_url(get_template_directory_uri().'/assets/mark.svg').'">';}add_action('wp_head','an_favicon',100);
